template <typename T, typename Enable = void>
struct Processor {
    static constexpr auto get() { return "Generic"; }
};

template <typename T>
struct Processor<T,
    std::enable_if_t<std::is_integral_v<T>>>
{
    static constexpr auto get() { return "Integral"; }
};

template <typename T>
struct Processor<T,
    std::enable_if_t<std::is_pointer_v<T>>>
{
    static constexpr auto get() { return "Pointer"; }
};

// Usage check:
// Processor<int>::get();      // Integral
// Processor<float>::get();    // Generic
// Processor<int*>::get();     // Pointer
